// === Tab: mySketch ===
const SCARRER_AMOUNT = 0.2;
const FRAME_PER_STEP = 20;
const INTERVAL = 2000;

let colors = ["#EFD6AF", "#DC7237", "#DA4740", "#E4AD9C", "#B6B15F", "#41403A", "#8BAEBA"];
let columns = 1;
let rows = 1;
let step = 0;
let scene = 0;

let indexes = [];
let holes = [];
let gradientShader;

function setup() {
	let w = max(windowWidth, windowHeight)*0.9;
  createCanvas(w, w, WEBGL);
  colorMode(RGB, 1, 1, 1, 1);
  pixelDensity(displayDensity());
  gl = this.canvas.getContext('webgl');
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
  gradientShader = createShader(vert, frag);
  noStroke();
  fill(0, 0, 0, 0);
  initScene();
}

function draw() {
  let wallColor = color(colors[0]);
  background(wallColor);
  translate(-width / 2, -height / 2, 0);
  shader(gradientShader);

  gradientShader.setUniform('wallColor', [red(wallColor), green(wallColor), blue(wallColor)]);

  for (let i = 0; i < columns * rows; i++) {
    if (scene == 0 && i > step) {
      break;
    }
    const hole = holes[indexes[i]];
    let depth = hole.depth;
		let diameter = hole.diameter;
		if (scene == 0) {
			depth = 0;
			if (i == step) {
				diameter = hole.diameter * (frameCount % FRAME_PER_STEP) / FRAME_PER_STEP;
			}
		} else if (scene == 1) {
			if (i == step) {
				depth = hole.depth * (frameCount % FRAME_PER_STEP) / FRAME_PER_STEP;
			} else if (i > step) {
				depth = 0;
			}
		}
    gradientShader.setUniform('color', [red(hole.color), green(hole.color), blue(hole.color)]);
    gradientShader.setUniform('depth', depth);
    push();
    translate(width / columns * hole.x, height / rows * hole.y, 0);
    plane(diameter);
    pop();
  }

  if (frameCount % FRAME_PER_STEP == FRAME_PER_STEP - 1) {
    step++;
  }
  if (step == columns * rows) {
    step = 0;
    scene++;
  }
  if (scene == 2) {
		let startTime = new Date();
		while (new Date() - startTime < INTERVAL);
    initScene();
  }
}

function initScene() {
  columns = Math.floor(random(2, 5));
  rows = columns;
  colors = shuffle(colors);
  indexes = shuffle(Array.from(new Array(columns * rows)).map((v, i) => i));
  holes = [];
  for (let i = 0; i < columns * rows; i++) {
    var diameter = random(width / columns / 6, width / columns / 1.5);
    var depth = random(0.1, 0.9);
    let c = color(colors[Math.floor(Math.random() * (colors.length - 1)) + 1]);

    let x = i % columns + 0.5 + random(-SCARRER_AMOUNT, SCARRER_AMOUNT);
    let y = int(i / rows) + 0.5 + random(-SCARRER_AMOUNT, SCARRER_AMOUNT);
    holes.push(new Hole(diameter, depth, c, x, y));
  }
  step = 0;
  scene = 0;
}

function Hole(diameter, depth, color, x, y) {
  this.diameter = diameter;
  this.depth = depth;
  this.color = color;
  this.x = x;
  this.y = y;
}

let vert = `
#ifdef GL_ES
precision mediump float;
#endif

// attributes, in
attribute vec3 aPosition;
attribute vec2 aTexCoord;

// attributes, out
varying vec2 vTexCoord;

// matrices
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

void main() {
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
  vTexCoord = aTexCoord;
}
`;

var frag = `
#ifdef GL_ES
precision mediump float;
#endif

varying highp vec2 vTexCoord;

uniform vec3 color;
uniform vec3 wallColor;
uniform float depth;

float map(float value, float inMin, float inMax, float outMin, float outMax) {
  return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

float overlay(float base, float blend) {
	return base<0.5?(2.0*base*blend):(1.0-2.0*(1.0-base)*(1.0-blend));
}

vec3 overlay(vec3 base, vec3 blend) {
	return vec3(overlay(base.r,blend.r),overlay(base.g,blend.g),overlay(base.b,blend.b));
}

vec3 overlay(vec3 base, vec3 blend, float opacity) {
	return (overlay(base, blend) * opacity + base * (1.0 - opacity));
}

void main(void) {
  vec2 p = vec2(vTexCoord.x - 0.5, vTexCoord.y - 0.5);
  float radius = length(p);

  if(radius > 0.5) {
    gl_FragColor = vec4(0.0);
  } else if(radius < map(depth,0.0,1.0,0.5,0.0)) {
    gl_FragColor = vec4(color, 1.0);
  } else {
    vec2 v = vec2(1.0, 1.0);
    float t = (dot(p, v) / (length(p) * length(v))+1.0)/2.0;
    gl_FragColor = vec4(overlay(wallColor, vec3(t*pow(radius, 0.2 )), 1.0), 1.0);
  }
}`;

